<script setup lang="ts">
definePageMeta({middleware:'admin'})
const db=useSupabaseClient(),schools=ref<any[]>([]),requests=ref<any[]>([]),students=ref<any[]>([]),domains=ref<any[]>([]),schoolId=ref(''),domain=ref(''),choice=ref<Record<string,string>>({}),error=ref(''),success=ref('')
async function load(){const r=await db.from('schools').select('id,name').order('name');schools.value=r.data||[];if(!schoolId.value&&schools.value.length)schoolId.value=schools.value[0].id;await loadSchool()}
async function loadSchool(){error.value='';if(!schoolId.value)return;const [a,b,c]=await Promise.all([db.from('student_account_requests').select('user_id,email,given_name,family_name,requested_at,status').eq('school_id',schoolId.value).eq('status','pending').order('requested_at'),db.from('students').select('id,student_number,given_name,family_name').eq('school_id',schoolId.value).order('family_name').limit(1000),db.from('school_email_domains').select('id,domain').eq('school_id',schoolId.value)]);requests.value=a.data||[];students.value=b.data||[];domains.value=c.data||[];error.value=a.error?.message||b.error?.message||c.error?.message||''}
onMounted(load)
async function addDomain(){error.value='';success.value='';const value=domain.value.trim().toLowerCase().replace(/^@/,'');const r=await db.from('school_email_domains').insert({school_id:schoolId.value,domain:value});if(r.error){error.value=r.error.message;return}domain.value='';success.value='Domain added';await loadSchool()}
async function removeDomain(id:string){const r=await db.from('school_email_domains').delete().eq('id',id);if(r.error)error.value=r.error.message;else await loadSchool()}
async function review(id:string,approve:boolean){error.value='';success.value='';if(approve&&!choice.value[id]){error.value='Select the matching student record first';return}const r=await db.rpc('review_student_account_request',{p_user_id:id,p_student_id:approve?choice.value[id]:null,p_approve:approve});if(r.error){error.value=r.error.message;return}success.value=approve?'Student account approved':'Request declined';await loadSchool()}
</script>
<template><div class="page"><div class="shell admin-section"><NuxtLink to="/dashboard">← Dashboard</NuxtLink><h1>Student Registration Approval</h1><p class="notice">Only approve a request after independently confirming the student's identity. The email domain alone is not proof of identity.</p><label>School<select v-model="schoolId" @change="loadSchool"><option v-for="s in schools" :key="s.id" :value="s.id">{{s.name}}</option></select></label><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="success" class="success">{{success}}</p><div class="card"><h2>Approved Email Domains</h2><form class="editor" @submit.prevent="addDomain"><label>School domain (e.g. school.vic.edu.au)<input v-model="domain" required placeholder="school.vic.edu.au"></label><button class="btn">Add Domain</button></form><div v-for="d in domains" :key="d.id" class="data-row"><span>@{{d.domain}}</span><button class="secondary" @click="removeDomain(d.id)">Remove</button></div><p v-if="!domains.length">No domains configured. Students cannot register until one is added.</p></div><div class="card"><h2>Pending Requests ({{requests.length}})</h2><div v-for="r in requests" :key="r.user_id" class="data-row"><div><strong>{{r.given_name}} {{r.family_name}}</strong><p>{{r.email}} · Requested {{new Date(r.requested_at).toLocaleDateString()}}</p></div><div><select v-model="choice[r.user_id]"><option value="">Match existing student…</option><option v-for="s in students" :key="s.id" :value="s.id">{{s.family_name}}, {{s.given_name}} ({{s.student_number}})</option></select><div class="actions"><button class="btn" @click="review(r.user_id,true)">Approve</button><button class="secondary" @click="review(r.user_id,false)">Decline</button></div></div></div><p v-if="!requests.length">No pending requests.</p></div></div></div></template>
